        (4281, 'try a different one', 'It''s lovely, but I''d like to try a different one.'),
        (4282, 'go well with', 'Something floral — what would go well with the scones?'),
        (4283, 'get a refill', 'It''s lovely — can I get a refill of the same tea?'),
        (4284, 'a pot of', 'A pot of Earl Grey, please — I''d like to take my time.'),
        (4285, 'the same style', 'Just the same style as last time, please.'),
        (4286, 'a little shorter', 'Just a little shorter, about two centimeters.'),
        (4287, 'the front too', 'Please trim the front too, about one centimeter.'),
        (4288, 'It is perfect', 'Thank you so much, it is perfect.'),
        (4289, 'something different', 'I''d like something different, but nothing too dramatic.'),
        (4290, 'add some layers', 'Could you add some layers around my face?'),
        (4291, 'keep the length', 'I''d like to keep the length and just tidy the ends.'),
        (4292, 'It''s exactly what I wanted', 'It''s exactly what I wanted, thank you so much.'),
        (4293, 'get a trim', 'Nothing big — I just want to get a trim.'),
        (4294, 'thin out', 'Could you thin it out? It feels really heavy.'),
        (4295, 'grow ~ out', 'No thanks — I''m growing them out.'),
        (4296, 'I''d like that', 'Yes, I''d like that.'),
        (4297, 'I can play', 'I can play with them tonight.'),
        (4298, 'know a lot about', 'I know a lot about music.'),
        (4299, 'Let''s call it ~', 'Let''s call it The Quiz Cats.'),
        (4300, 'join a team', 'Sure, I''d love to join a team tonight.'),
        (4301, 'My strong point is ~', 'My strong point is music, so I''ll take those questions.'),
        (4302, 'think of a name', 'Give me a minute to think of a name.'),
        (4303, 'Let''s go with ~', 'Let''s go with The Pub Owls, then.'),
        (4304, 'join in', 'Sure, I''d love to join in — sounds fun!'),
        (4305, 'give it a go', 'Never, but I''ll give it a go!'),
        (4306, 'know a thing or two about', 'I know a thing or two about music, so I''ll take that round.'),
        (4307, 'I took the bus', 'I took the bus and then the subway.'),
        (4308, 'get my money back', 'So I can get my money back?'),
        (4309, 'three more days', 'I am here for three more days.'),
        (4310, 'I ride every day', 'I ride every day, morning and evening.'),
        (4311, 'transfer to ~', 'I came from Green Park and had to transfer to Line 2.'),
        (4312, 'I need to get to ~', 'Thanks. I need to get to King''s Cross before six.'),
        (4313, 'until Friday', 'I''m here until Friday and I''ll use the subway a lot.'),
        (4314, 'It''s worth it', 'If the pass saves money, it''s worth it for me.'),
        (4315, 'tap', 'I tapped in at King''s Cross, but the gate beeped when I tapped out.'),
        (4316, 'be overcharged', 'I think I was overcharged — five pounds for one short ride.'),
        (4317, 'off-peak', 'I''ll be riding a few more days, mostly off-peak — is that cheaper?'),
        (4318, 'I have two hours', 'I have two hours before lunch.'),
        (4319, 'an easy walk', 'The lake path is an easy walk.'),
        (4320, 'I have ~ with me', 'I have water and snacks with me.'),
        (4321, 'a raincoat', 'There is a raincoat in my bag.'),
        (4322, 'go hiking', 'I go hiking about twice a month, mostly on weekends.'),
        (4323, 'the easy one', 'I''ll take the easy one by the lake.'),
        (4324, 'in my backpack', 'I packed a first aid kit and a torch in my backpack.'),
        (4325, 'enough water', 'I''m not sure I have enough water for the whole walk.'),
        (4326, 'steep', 'How steep is the hill route? I''m not in great shape.'),
        (4327, 'rain gear', 'I''ve got water and snacks, but no rain gear.'),
        (4328, 'make it to the top', 'Not really, but I want to make it to the top today.')
    ) AS expected(id, expression_text, sentence_text)
    LEFT JOIN writing_expression we ON we.id = expected.id
    WHERE we.id IS NULL
       OR we.target_expression_text IS DISTINCT FROM expected.expression_text
       OR we.representative_sentence_text IS DISTINCT FROM expected.sentence_text;

    IF mismatched > 0 THEN
        RAISE EXCEPTION 'LAN-601 pronunciation assets: % writing_expression rows are missing or differ from the texts the audio was generated from (first id %).',
            mismatched, first_mismatch;
    END IF;
END
$$;

ON CONFLICT (writing_expression_id, accent_locale) DO UPDATE SET
    expression_audio_url = EXCLUDED.expression_audio_url,
    sentence_audio_url = EXCLUDED.sentence_audio_url,
    words = EXCLUDED.words,
    updated_at = now();

DO $$
BEGIN
    IF (SELECT count(*) FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 4001 AND 4328) <> 984 THEN
        RAISE EXCEPTION 'LAN-601 pronunciation assets: expected 984 rows for 4001~4328';
    END IF;

    IF EXISTS (
        SELECT 1 FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 4001 AND 4328
        GROUP BY accent_locale
        HAVING count(*) <> 328
    ) OR (SELECT count(DISTINCT accent_locale) FROM expression_pronunciation_asset
          WHERE writing_expression_id BETWEEN 4001 AND 4328) <> 3 THEN
        RAISE EXCEPTION 'LAN-601 pronunciation assets: every accent locale must have 328 rows';
    END IF;

    IF EXISTS (
        SELECT 1 FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 4001 AND 4328
          AND sentence_audio_url IS NULL
    ) THEN
        RAISE EXCEPTION 'LAN-601 pronunciation assets: sentence audio URL is missing';
    END IF;

    IF (SELECT count(*) FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 4001 AND 4328
          AND expression_audio_url IS NULL) <> 186 THEN
        RAISE EXCEPTION 'LAN-601 pronunciation assets: expected 186 templated expressions without expression audio';
    END IF;
END
$$;
